import { build } from 'esbuild';
import { fileURLToPath } from 'url';
import { dirname } from 'path';
import { copyFileSync, mkdirSync } from 'fs';
import { existsSync } from 'fs';

const __dirname = dirname(fileURLToPath(import.meta.url));

// Ensure dist-electron directory exists
if (!existsSync('dist-electron')) {
  mkdirSync('dist-electron', { recursive: true });
}

// Build Electron main process
await build({
  entryPoints: ['electron-main.js'],
  bundle: true,
  external: ['electron'],
  outfile: 'dist-electron/main.js',
  platform: 'node',
  target: 'node18',
  format: 'esm',
});

// Copy preload script
copyFileSync('preload.js', 'dist-electron/preload.js');

console.log('✓ Built Electron main process');
console.log('✓ Copied preload script');

